# plotting code for SLiM 6 performance results
#
# Benjamin C. Haller, 30 September 2026

# the data here were generated by `_performance_tests.txt` on a 2022 Mac Studio (Mac13,2; Apple M1 Ultra; 128 GB RAM).
# the SLiM 6 data were generated by SLiM 6.0b1 (but nothing changed for SLiM 6.0 final that would affect runtimes).
# note that the run lengths of the models are tailored to produce runtimes of ~30 s on that machine, so these plots use the same y axis.
# note also that timing results are stochastic and irreproducible, and will depend on the hardware and software environment.


plot_perf <- function(title, old, old_name, new, new_name, y_text=10.0)
{
	df <- data.frame(old, new)
	speedup <- mean(old) / mean(new)
	roundedSpeedup <- round(speedup * 100) / 100
	if (roundedSpeedup >= 1.0) {
		speedupText <- paste(format(roundedSpeedup, nsmall=2), "× faster", sep="")
		speedupColor <- "red"
	} else {
		speedupText <- paste(format(roundedSpeedup, nsmall=2), "× as fast", sep="")
		speedupColor <- "royalblue"
	}
	range(old, new)
	quartz(title, 3, 3)
	par(mai=c(0.75, 0.75, 0.1, 0.1), mgp=c(2.5, 0.5, 0))
	boxplot(df, ylim=c(0, 40), boxwex=0.5, pch=19, cex=0.5, cex.axis = 0.9, names=c(old_name, new_name), xlab="", ylab="runtime (seconds)")
	text(1.5, y_text, speedupText, adj=c(0.5, 0.5), cex=1.5, col=speedupColor)
	mtext("100 replicates", side=1, line=2.5, cex=0.75, font=3)
	box()
}


